        interaction.attachUnsettled(Collections.singletonMap(deliveryTag, null)).attach().consumeResponse(Attach.class);
        Attach resumeAttach = interaction.getLatestResponse(Attach.class);
        Map<Binary, DeliveryState> unsettled = resumeAttach.getUnsettled();
        assertThat(unsettled, is(notNullValue()));
        assertThat(unsettled.entrySet(), hasSize(1));
        Map.Entry<Binary, DeliveryState> entry = unsettled.entrySet().iterator().next();
        assertThat(entry.getKey(), is(equalTo(deliveryTag)));
        interaction.flowNextIncomingId(UnsignedInteger.ONE).flowLinkCredit(UnsignedInteger.ONE).flowHandleFromLinkHandle().flow().receiveDelivery();
        transfers = interaction.getLatestDelivery();
        assertThat(transfers, hasSize(1));
        Transfer resumeTransfer = transfers.get(0);
        assertThat(resumeTransfer.getResume(), is(equalTo(true)));
        assertThat(resumeTransfer.getDeliveryTag(), is(equalTo(deliveryTag)));
        assertThat(resumeTransfer.getPayload(), is(notNullValue()));
        interaction.dispositionSettled(true).dispositionState(new Accepted()).dispositionRole(Role.RECEIVER).disposition();
        transport.doCloseConnection();
        if (getBrokerAdmin().isQueueDepthSupported()) {
            assertThat(getBrokerAdmin().getQueueDepthMessages(BrokerAdmin.TEST_QUEUE_NAME), Matchers.is(Matchers.equalTo(0)));
        }
    }
}

@Ignore("QPID-7845")
@Test
@SpecificationTest(section = "2.6.13", description = "When a suspended link having unsettled deliveries is resumed, the unsettled field from the" + " attach frame will carry the delivery-tags and delivery state of all deliveries" + " considered unsettled by the issuing link endpoint.")
public void resumeSendingLinkSinglePartialDelivery() throws Exception {
    final String destination = BrokerAdmin.TEST_QUEUE_NAME;
    final Binary deliveryTag = new Binary("testDeliveryTag".getBytes(StandardCharsets.UTF_8));
    QpidByteBuffer[] messagePayload = Utils.splitPayload("testData1", 2);
    try (FrameTransport transport = new FrameTransport(_brokerAddress).connect()) {
        final UnsignedInteger linkHandle1 = UnsignedInteger.ZERO;
        final Interaction interaction = transport.newInteraction();
        interaction.negotiateProtocol().consumeResponse().open().consumeResponse(Open.class).begin().consumeResponse(Begin.class);
        // 1. attach with ReceiverSettleMode.SECOND
        interaction.attachHandle(linkHandle1).attachRole(Role.SENDER).attachTargetAddress(destination).attach().consumeResponse(Attach.class).consumeResponse(Flow.class);
        // 2. send a partial delivery
        interaction.transferHandle(linkHandle1).transferDeliveryId(UnsignedInteger.ZERO).transferDeliveryTag(deliveryTag).transferMore(true).transferPayload(Collections.singletonList(messagePayload[0])).transfer();
        // 3. detach the link
        interaction.detach().consumeResponse(Detach.class);
        // 4. resume the link
        final UnsignedInteger linkHandle2 = UnsignedInteger.ONE;
        final Attach responseAttach2 = interaction.attachHandle(linkHandle2).attachUnsettled(Collections.singletonMap(deliveryTag, null)).attach().consumeResponse().getLatestResponse(Attach.class);
        // 5. assert content of unsettled map
        assertThat(responseAttach2.getTarget(), is(notNullValue()));
        final Map<Binary, DeliveryState> remoteUnsettled = responseAttach2.getUnsettled();
        assertThat(remoteUnsettled, is(notNullValue()));
        assertThat(remoteUnsettled.keySet(), is(equalTo(Collections.singleton(deliveryTag))));
        interaction.transferHandle(linkHandle2).transferResume(true).transfer().sync().transferMore(false).transferPayload(Collections.singletonList(messagePayload[1])).transfer();
        boolean settled = false;
        do {
            interaction.consumeResponse();
            Response<?> response = interaction.getLatestResponse();
            assertThat(response, is(notNullValue()));
            Object body = response.getBody();
            if (body instanceof Disposition) {
                Disposition disposition = (Disposition) body;
                assertThat(disposition.getSettled(), is(Matchers.equalTo(true)));
                assertThat(disposition.getFirst(), equalTo(UnsignedInteger.ZERO));
                settled = true;
            } else if (!(body instanceof Flow)) {
                fail("Unexpected response " + body);
            }
        } while (!settled);
        transport.doCloseConnection();
    }
}

@Test
@SpecificationTest(section = "2.2", description = "Prior to sending any frames on a connection, each peer MUST start by sending a protocol header that indicates " + "the protocol version used on the connection. The protocol header consists of the upper case ASCII letters “AMQP” " + "followed by a protocol id of zero, followed by three unsigned bytes representing the major, minor, and revision of " + "the protocol version (currently 1 (MAJOR), 0 (MINOR), 0 (REVISION)).")
public void successfulHeaderExchange() throws Exception {
    final InetSocketAddress addr = getBrokerAdmin().getBrokerAddress(BrokerAdmin.PortType.ANONYMOUS_AMQP);
    try (FrameTransport transport = new FrameTransport(addr).connect()) {
        byte[] protocolHeader = "AMQP\0\1\0\0".getBytes(StandardCharsets.UTF_8);
        final byte[] response = transport.newInteraction().protocolHeader(protocolHeader).negotiateProtocol().consumeResponse().getLatestResponse(byte[].class);
        assertArrayEquals("Unexpected protocol header response", protocolHeader, response);
    }
}

@Test
@SpecificationTest(section = "2.2", description = " A client might request use of a protocol id that is unacceptable to a server. [...]" + "In this case, the server MUST send a protocol header with an acceptable protocol id" + "(and version) and then close the socket.")
public void unacceptableProtocolIdSent_SaslAcceptable() throws Exception {
    final InetSocketAddress addr = getBrokerAdmin().getBrokerAddress(BrokerAdmin.PortType.AMQP);
    try (FrameTransport transport = new FrameTransport(addr).connect()) {
        byte[] rawHeaderBytes = "AMQP\0\1\0\0".getBytes(StandardCharsets.UTF_8);
        final byte[] response = transport.newInteraction().protocolHeader(rawHeaderBytes).negotiateProtocol().consumeResponse().getLatestResponse(byte[].class);
        byte[] expectedSaslHeaderBytes = "AMQP\3\1\0\0".getBytes(StandardCharsets.UTF_8);
        assertArrayEquals("Unexpected protocol header response", expectedSaslHeaderBytes, response);
        transport.assertNoMoreResponses();
    }
}

